const now = Date.now();
const base = "InternetGatewayDevice.Firewall.X_ZTE-COM_ServiceControl.IPV4ServiceControl";

// 1. Validasi perangkat
const manufacturer = declare(
  "InternetGatewayDevice.DeviceInfo.Manufacturer",
  {value: now}
);
const productClass = declare(
  "InternetGatewayDevice.DeviceInfo.ProductClass",
  {value: now}
);

if (
  !manufacturer.value ||
  manufacturer.value[0] !== "ZTE" ||
  !productClass.value ||
  productClass.value[0] !== "F672Y"
) {
  log("RF ACL: perangkat bukan ZTE F672Y, dilewati.");
} else {
  // 2. Baca instance ACL yang sudah ada
  const instances = declare(base + ".*", {path: now});
  let httpInstance = null;
  let emptyInstance = null;

  for (const item of instances) {
    const service = declare(item.path + ".ServiceType", {value: now});
    const type = service.value ? String(service.value[0] || "") : "";

    if (type === "HTTP" && !httpInstance) {
      httpInstance = item.path;
    } else if (type === "" && !emptyInstance) {
      emptyInstance = item.path;
    }
  }

  // 3. Gunakan HTTP yang sudah ada, atau objek kosong
  let target = httpInstance || emptyInstance;

  // 4. Jika belum ada, buat satu instance dengan alias HTTP
  if (!target) {
    const httpAlias = base + ".[ServiceType:HTTP]";
    declare(httpAlias, {path: now}, {path: 1});
    target = httpAlias;
  }

  // 5. Konfigurasi ACL HTTP
  declare(target + ".ServiceType", null, {value: "HTTP"});
  declare(target + ".Ingress", null, {value: "WAN_ALL"});
  declare(target + ".IPStart", null, {value: "0.0.0.0"});
  declare(target + ".IPEnd", null, {value: "0.0.0.0"});
  declare(target + ".Mode", null, {value: "Accept"});
  declare(target + ".Enable", null, {value: true});

  log("RF ACL: konfigurasi HTTP F672Y dideklarasikan pada " + target);
}

const now = Date.now();

// Clear cached data model to force a refresh
clear("Device", now);
clear("InternetGatewayDevice", now);

// RF MEDIA - Bulletproof & Informative Default Provision
const now = Date.now();
const daily = now - 86400000; 
const hourly = now - 3600000;
const update = now - 120000; // 2 minutes (auto-refresh on inform)

// 1. Safe Brand & Product Detection
const merkDecl = declare("DeviceID.Manufacturer", {value: 1});
const merk = (merkDecl && merkDecl.value && merkDecl.value[0]) ? String(merkDecl.value[0]) : "";

// 2. Basic Info & Uptime
declare("DeviceID.ProductClass", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.HardwareVersion", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.SoftwareVersion", {path: daily, value: daily});
declare("InternetGatewayDevice.DeviceInfo.UpTime", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANCommonInterfaceConfig.WANAccessType", {path: daily, value: daily});

// 3. Optical Power & Temp (Safe paths without forced values)
if (merk.includes("ZTE") || merk.includes("ZICG")) {
  declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.TransceiverTemperature", {path: update, value: update});
} else if (merk.includes("Huawei")) {
  declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.TransceiverTemperature", {path: update, value: update});
} else {
  // CIOT / GM220-S / M63X / CT-COM
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TransceiverTemperature", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower", {path: update, value: update});
  declare("InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.TransceiverTemperature", {path: update, value: update});
}

// 4. WAN Connection
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Enable", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Name", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ConnectionType", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.NATEnabled", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ConnectionStatus", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Password", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_VlanID", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANIDMark", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANMode", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_VLAN", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ZTE-COM_VlanID", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.VLANID", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_BROADCOM_COM_VLANID", {path: update, value: update});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_ServiceList", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_ServiceList", {path: daily, value: daily});
declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_SERVICELIST", {path: daily, value: daily});
declare("VirtualParameters.VlanID", {path: update, value: update});

// 5. WLAN (WiFi) Configuration
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*", {path: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.SSID", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.BeaconType", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Enable", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Channel", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.TotalAssociations", {path: update, value: update});

// 5.1 WiFi Connected Clients (Associated Devices) - Auto fetch without manual summon
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.AssociatedDeviceMACAddress", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.AssociatedDeviceIPAddress", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.AssociatedDeviceAuthenticationState", {path: update, value: update});

if (merk.includes("Huawei")) {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.X_HW_RSSI", {path: update, value: update});
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.X_HW_AssociatedDevicedescriptions", {path: update, value: update});
} else if (merk.includes("ZTE") || merk.includes("ZICG")) {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.AssociatedDeviceRssi", {path: update, value: update});
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.X_ZTE-COM_RSSI", {path: update, value: update});
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.AssociatedDevice.*.X_ZTE-COM_DeviceName", {path: update, value: update});
}
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Enable", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.Channel", {path: update, value: update});

if (merk.includes("ZTE") || merk.includes("ZICG") || merk.includes("Huawei")) {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.PreSharedKey.1.KeyPassphrase", {path: daily, value: daily});
} else {
  declare("InternetGatewayDevice.LANDevice.1.WLANConfiguration.*.KeyPassphrase", {path: daily, value: daily});
}

// 6. LAN Management & Gateway Config
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPRouters", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.DHCPServerEnable", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MinAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MaxAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.DNSServers", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPInterface.1.IPInterfaceIPAddress", {path: daily, value: daily});
declare("InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.IPInterface.1.IPInterfaceSubnetMask", {path: daily, value: daily});

// 7. Ethernet Physical Ports (Safe object path)
declare("InternetGatewayDevice.LANDevice.1.LANEthernetInterfaceConfig.*", {path: daily});

// 8. Connected User Devices (Hosts object path)
declare("InternetGatewayDevice.LANDevice.1.Hosts.HostNumberOfEntries", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.HostName", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.IPAddress", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.MACAddress", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.InterfaceType", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.Active", {path: update, value: update});
declare("InternetGatewayDevice.LANDevice.1.Hosts.Host.*.LeaseTimeRemaining", {path: update, value: update});

// 9. Virtual Parameters
declare("VirtualParameters.RXPower", {path: update, value: update});
declare("VirtualParameters.pppoeUsername", {path: update, value: update});
declare("VirtualParameters.pppoeUsername2", {path: update, value: update});
declare("VirtualParameters.pppoeIP", {path: update, value: update});
declare("VirtualParameters.pppIP", {path: update, value: update});
declare("VirtualParameters.pppUsername", {path: update, value: update});
declare("VirtualParameters.getdeviceuptime", {path: update, value: update});
declare("VirtualParameters.getpppuptime", {path: update, value: update});
declare("VirtualParameters.uptimeDevice", {path: update, value: update});
declare("VirtualParameters.gettemp", {path: update, value: update});
declare("VirtualParameters.temp", {path: update, value: update});
declare("VirtualParameters.getponmode", {path: daily, value: daily});
declare("VirtualParameters.activedevices", {path: update, value: update});
declare("VirtualParameters.WlanSSID", {path: update, value: update});
declare("VirtualParameters.WlanPassword", {path: update, value: update});
declare("VirtualParameters.MacAddress", {path: daily, value: daily});
declare("VirtualParameters.pppoeMac", {path: daily, value: daily});
declare("VirtualParameters.PonMac", {path: daily, value: daily});
declare("VirtualParameters.IPTR069", {path: update, value: update});

// RF MEDIA - Provision Inform
const AcsUser = "__RF_MEDIA_ACS_USERNAME__";
const AcsPass = "__RF_MEDIA_ACS_PASSWORD__";
const ConnReqUser = "__RF_MEDIA_CONNREQ_USERNAME__";
const ConnReqPass = "__RF_MEDIA_CONNREQ_PASSWORD__";
const informInterval = 300;

const now = Date.now();
const daily = now - 86400000;
const hourly = now - 3600000;

const brandDecl = declare("DeviceID.Manufacturer", {value: daily});
const brand = (brandDecl && brandDecl.value && brandDecl.value[0]) ? String(brandDecl.value[0]) : "";

if (brand !== "MikroTik") {
  declare("InternetGatewayDevice.ManagementServer.Username", {value: daily}, {value: AcsUser});
  declare("InternetGatewayDevice.ManagementServer.Password", {value: daily}, {value: AcsPass});
  declare("InternetGatewayDevice.ManagementServer.ConnectionRequestUsername", {value: daily}, {value: ConnReqUser});
  declare("InternetGatewayDevice.ManagementServer.ConnectionRequestPassword", {value: daily}, {value: ConnReqPass});
  declare("InternetGatewayDevice.ManagementServer.PeriodicInformEnable", {value: daily}, {value: true});
  declare("InternetGatewayDevice.ManagementServer.PeriodicInformInterval", {value: daily}, {value: informInterval});
} else {
  declare("Device.ManagementServer.Username", {value: daily}, {value: AcsUser});
  declare("Device.ManagementServer.Password", {value: daily}, {value: AcsPass});
  declare("Device.ManagementServer.ConnectionRequestUsername", {value: daily}, {value: ConnReqUser});
  declare("Device.ManagementServer.ConnectionRequestPassword", {value: daily}, {value: ConnReqPass});
  declare("Device.ManagementServer.PeriodicInformEnable", {value: daily}, {value: true});
  declare("Device.ManagementServer.PeriodicInformInterval", {value: daily}, {value: informInterval});
}
